export type BuiltinSkill = { readonly id:string; readonly name:string; readonly priority:"P0"|"P1"; readonly category:string; readonly description:string; readonly engine:string; readonly requires:readonly string[]; readonly scopes:readonly string[]; readonly upstream:string; readonly license:string; readonly optIn:boolean; readonly content:string };
export const BUILTIN_SKILLS:readonly BuiltinSkill[] = JSON.parse("[{\"id\":\"browser-operator\",\"name\":\"Browser Operator\",\"priority\":\"P0\",\"category\":\"browser\",\"description\":\"Operate an authorized browser using DOM snapshots and repeatable actions.\",\"engine\":\"agent-browser + Microsoft Playwright MCP\",\"requires\":[\"agent-browser\"],\"scopes\":[\"browser:read\",\"browser:interact\"],\"upstream\":\"https://github.com/vercel-labs/agent-browser\",\"license\":\"Apache-2.0\",\"optIn\":false,\"content\":\"---\\nname: browser-operator\\ndescription: Operate an authorized browser using DOM snapshots and repeatable actions.\\npriority: P0\\ncategory: browser\\nstatus: builtin-guidance\\n---\\n\\n# Browser Operator\\n\\n**Scope:** agent-browser + Microsoft Playwright MCP. **Source:** https://github.com/vercel-labs/agent-browser\\n\\n## Workflow\\n\\nUse existing Remote Arc shared_tab_read for read-only work on a tab the user shared first. In the user's own browser with the Remote Arc Browser extension 0.4.0 or later, shared_tab_open opens a tab on a site the user allowed (SITE_NOT_ALLOWED means ask the user to click Allow once) and shared_tab_act clicks, fills, selects, presses keys, navigates and waits there; final submits need effect=submit with an idempotency_key and are settled with action=confirm. For multi-step work on a linked computer, use the Remote Arc Browser Runner (browser_runner_*) when it is enabled for the device: a separate Runner window by default, or the user's own Chrome with browser=your_chrome when the user asks for it; otherwise use locally approved agent-browser or Playwright, in a separate profile; never attach to personal sessions without explicit permission. Steps: 1) confirm device, origin and requested interaction scope; 2) snapshot DOM and locate stable accessible selectors; 3) plan bounded clicks/fills; 4) ask permission for modifying site state, checkout, account settings, irreversible submissions; 5) verify changed page and report evidence. Keep navigation URLs within allowed origins. Never use anti-bot evasion, cookie export, credential harvesting or silent downloads. Headless browser must be explicitly chosen; a Chrome extension tab is a different permission boundary. CLI examples only after installation: agent-browser open https://example.com; agent-browser snapshot -i; agent-browser close. If browser CLI is absent, use existing Remote Arc browser tools and report limits.\\n\\n## Device and permission gates\\n\\nRequired authorization scopes: browser:read, browser:interact. Scripts, OS/desktop actions, external service side effects, media generation and paid API usage require independent user-approved execution permissions. This skill does not elevate Remote Arc Tool privileges or authorize use of hidden credentials.\\n\\n## Preflight\\n\\nCheck the engines this skill names before relying on them, with tools you already have (for example `<engine> --version` through start_process, or list_directory on its install folder). Missing executors must be installed explicitly on the correct user device. A Skill being built-in is NOT evidence an engine is present.\\n\\n## Evidence of completion\\n\\nReport input constraints, executed tools and device, verified output path/result, permissions used, cost (if known) and failures. Do not imply successful execution from merely writing a plan.\\n\"},{\"id\":\"autonomous-browser\",\"name\":\"Autonomous Browser\",\"priority\":\"P0\",\"category\":\"browser\",\"description\":\"Plan multi-step browser work using browser-use with an approved model budget.\",\"engine\":\"browser-use Python library\",\"requires\":[\"browser-use\"],\"scopes\":[\"browser:read\",\"browser:interact\"],\"upstream\":\"https://github.com/browser-use/browser-use\",\"license\":\"MIT\",\"optIn\":true,\"content\":\"---\\nname: autonomous-browser\\ndescription: Plan multi-step browser work using browser-use with an approved model budget.\\npriority: P0\\ncategory: browser\\nstatus: builtin-guidance\\n---\\n\\n# Autonomous Browser\\n\\n**Scope:** browser-use Python library. **Source:** https://github.com/browser-use/browser-use\\n\\n## Workflow\\n\\nUse only when deterministic DOM actions fail or multi-step planning is essential. browser-use is a separate Python reasoning engine and may use chargeable LLM APIs. Do not create paid cloud sessions by default. Require an explicit device/browser permission, named objective, URL allowlist, max iterations, timeout, model budget and human checkpoints. Prefer local browser and a caller-provided model account; never assume API credits are free. Inspect planned actions, execute only authorized ones, and save a scrubbed action/evidence log. Stop on CAPTCHA, account lock, MFA, payments, new unknown domains and repeated failures. A user can instead choose the zero-model-cost Browser Operator. No autostart and no implicit installation.\\n\\n## Device and permission gates\\n\\nRequired authorization scopes: browser:read, browser:interact. Scripts, OS/desktop actions, external service side effects, media generation and paid API usage require independent user-approved execution permissions. This skill does not elevate Remote Arc Tool privileges or authorize use of hidden credentials.\\n\\n## Preflight\\n\\nCheck the engines this skill names before relying on them, with tools you already have (for example `<engine> --version` through start_process, or list_directory on its install folder). Missing executors must be installed explicitly on the correct user device. A Skill being built-in is NOT evidence an engine is present.\\n\\n## Evidence of completion\\n\\nReport input constraints, executed tools and device, verified output path/result, permissions used, cost (if known) and failures. Do not imply successful execution from merely writing a plan.\\n\"},{\"id\":\"desktop-operator\",\"name\":\"Desktop Operator\",\"priority\":\"P0\",\"category\":\"desktop\",\"description\":\"Move pointer, drag, type and click in a permitted local desktop session.\",\"engine\":\"PyAutoGUI / native OS accessibility\",\"requires\":[\"python3\"],\"scopes\":[\"computer:read\",\"computer:write\"],\"upstream\":\"https://github.com/asweigart/pyautogui\",\"license\":\"BSD-3-Clause\",\"optIn\":true,\"content\":\"---\\nname: desktop-operator\\ndescription: Move pointer, drag, type and click in a permitted local desktop session.\\npriority: P0\\ncategory: desktop\\nstatus: builtin-guidance\\n---\\n\\n# Desktop Operator\\n\\n**Scope:** PyAutoGUI / native OS accessibility. **Source:** https://github.com/asweigart/pyautogui\\n\\n## Workflow\\n\\nPrefer native accessibility tree/API when available, then screenshot-based coordinates as fallback. On macOS request Accessibility + Screen Recording permission through the OS; on Windows control the actual Windows desktop via an explicit native helper, not a WSL X display. Use existing Remote Arc process permission and scoped device approval for scripts. For mouse movement, calculate a short monotonic path with easing, bounded duration and screen dimensions; screenshot before/after to verify. Never silently move the pointer on a device the user is actively using. Confirm focused app and coordinates before typing, especially passwords, financial transfers or destructive actions. Do not attempt to bypass OS consent dialogs. PyAutoGUI installation and permission are opt-in per device.\\n\\n## Device and permission gates\\n\\nRequired authorization scopes: computer:read, computer:write. Scripts, OS/desktop actions, external service side effects, media generation and paid API usage require independent user-approved execution permissions. This skill does not elevate Remote Arc Tool privileges or authorize use of hidden credentials.\\n\\n## Preflight\\n\\nCheck the engines this skill names before relying on them, with tools you already have (for example `<engine> --version` through start_process, or list_directory on its install folder). Missing executors must be installed explicitly on the correct user device. A Skill being built-in is NOT evidence an engine is present.\\n\\n## Evidence of completion\\n\\nReport input constraints, executed tools and device, verified output path/result, permissions used, cost (if known) and failures. Do not imply successful execution from merely writing a plan.\\n\"},{\"id\":\"video-creator\",\"name\":\"Video Creator\",\"priority\":\"P0\",\"category\":\"media\",\"description\":\"Make finished videos (promos, explainers, vibe/抖音 clips) on the user's computer with OpenFilm; local voice-over, music and maps, no keys for the core.\",\"engine\":\"OpenFilm 0.2.5 + FFmpeg\",\"requires\":[\"node\",\"ffmpeg\",\"git\"],\"scopes\":[\"computer:read\",\"computer:write\"],\"upstream\":\"https://github.com/openfilm/openfilm\",\"license\":\"MIT; generated media follows each provider's terms\",\"optIn\":true,\"content\":\"---\\nname: video-creator\\ndescription: Make finished videos (promos, explainers, launch clips, social cuts) on the user's own computer with OpenFilm, no API keys needed.\\npriority: P0\\ncategory: media\\nstatus: builtin-guidance\\n---\\n\\n# Video Creator\\n\\n**Engine:** OpenFilm 0.2.5 (MIT, `npx -y openfilm@0.2.5`) + FFmpeg. **Source:** https://github.com/openfilm/openfilm\\n\\nYou write the film; the user's computer renders it. Text, graphics, animation, charts, maps, screenshots and the user's own footage need **no paid model API**. Local rendering still consumes device compute, electricity, storage and downloads; the calling AI may consume its plan allowance or Arc Credits. Optional local voice-over/music require separate model downloads and the user's explicit approval when large. AI-generated images/video may need a paid provider the user connects with their own key.\\n\\n## Preflight (once per computer)\\n\\nUse a computer whose tools include `start_process`, `write_file` and `read_file`, inside one of its Trusted Write Locations.\\n- Windows (cmd.exe): `node -v & ffmpeg -version | findstr /b \\\"ffmpeg version\\\" & git --version`\\n- macOS / Linux: `node -v; ffmpeg -version | head -1; git --version`\\nNeed Node 22.2+, ffmpeg and git. If one is missing, tell the user exactly what to install (nodejs.org, ffmpeg.org) and stop; never install system software silently. The first OpenFilm run downloads a headless Chromium (~115 MB) once: tell the user it can take a minute.\\n\\n**Every OpenFilm command must run unattended:** set `OPENFILM_NO_BROWSER=1` and `OPENFILM_NO_UPDATE_CHECK=1`. Without them a non-interactive run opens Studio in the user's browser after 15 s.\\n- Windows: `set OPENFILM_NO_BROWSER=1& set OPENFILM_NO_UPDATE_CHECK=1& npx -y openfilm@0.2.5 <command>`\\n- macOS / Linux: `OPENFILM_NO_BROWSER=1 OPENFILM_NO_UPDATE_CHECK=1 npx -y openfilm@0.2.5 <command>`\\nRun `npx -y openfilm@0.2.5` once (no command) and read its printed manual whole: it is the format reference.\\n\\n## What makes it look good\\n\\nOpenFilm composes and renders; it does not invent footage. A film of only text and shapes looks like animated slides. Quality comes from **real material**, so gather it before writing pages:\\n- the user's own footage, photos, logo and screen recordings (ask for them, or find them in the folders they point to);\\n- product screenshots or recordings of the user's own site or app, made with the tools you already have;\\n- charts and diagrams drawn in code from real data.\\nThen direct it like an editor: camera moves on stills (slow push-in/pan), cuts on the beat, big type on few words, depth with layered tracks, consistent palette. Generated images, AI video and AI voice look most \\\"cinematic\\\" but need the user's keys and cost money (see below): offer them, never assume them. Say plainly what is achievable with the material available.\\n\\n## Workflow\\n\\n1. **Brief.** Settle length (default 30 s), frame (1920×1080 landscape; 1080×1920 for Reels/Shorts/TikTok), language, message, brand colours and any assets the user owns. Ask only what you cannot infer.\\n2. **Project.** Make a new folder named after the film inside a Trusted Write Location (e.g. `<root>\\\\films\\\\launch-30s`). Never write into the user's existing projects.\\n3. **Pages.** One shot per page (`title.html`, `steps.html`, …), plus a background page for the whole length. Each page sets `window.film = { duration, frame(t) }` and **draws only from t**: no timers, `requestAnimationFrame`, CSS transitions, `Math.random()` or `Date`. Shared colours/helpers go in one `shared.js` the pages import. Keep text inside its box (long strings overflow cards).\\n4. **film.html.** `<meta name=\\\"viewport\\\" content=\\\"width=1920, height=1080\\\">`; one `<section>` per track, top track first (titles over footage, background last); each clip has `at` (start second); pictures and pages without a `duration` need `#t=0,length`; sound is only `<audio>` clips in film.html, never in pages.\\n5. **Sound without keys.** Generate a bed with ffmpeg into `assets/`, normalised so it is audible, e.g. a soft A-major pad:\\n   `ffmpeg -y -f lavfi -i \\\"sine=f=220:d=30\\\" -f lavfi -i \\\"sine=f=277.18:d=30\\\" -f lavfi -i \\\"sine=f=329.63:d=30\\\" -f lavfi -i \\\"sine=f=110:d=30\\\" -filter_complex \\\"[0][1][2][3]amix=inputs=4:normalize=1,tremolo=f=0.5:d=0.35,loudnorm=I=-18:TP=-2,afade=t=in:d=2,afade=t=out:st=27:d=3\\\" -ar 48000 assets/bed.wav`\\n   Use the user's own music only if they provide it.\\n6. **Check with `look`** (run in the film folder, `background:true`, then wait on the process). It must report \\\"same t, same picture\\\"; fix every warning (too-quiet sound, nondeterministic page). Read the contact sheet PNG it prints (`.film/cache/look/0-30s.png`) and fix overflow, collisions and empty frames before rendering.\\n7. **Render** with `render` (`background:true`; add `--4k` or `--fps 60` only when asked). A 30 s 1080p film rendered in ~25 s on a desktop with 4 parallel browsers; expect longer on laptops. Wait for the process to exit; do not sleep-and-poll in short loops.\\n8. **Verify** the actual file: `ffprobe -v error -show_entries format=duration,size:stream=codec_name,width,height,nb_frames -of json <film>.mp4`. Duration, size and frame count must match the brief; check loudness with `ffmpeg -i <film>.mp4 -af volumedetect -vn -f null -` (mean around -20 dB, not below -35).\\n9. **Deliver the video itself.** The MP4 is `<folder>/<folder name>.mp4` beside film.html. Give the user its exact path; if they are away from that computer, use `create_file_resource` for a short-lived download link, or upload it where they asked (Browser Runner accepts video). Never open Studio or a browser on the user's screen; mention only that `npx -y openfilm@0.2.5 open <folder>` opens the film in Studio if they want to edit it by hand.\\n\\n## Voice-over, music and maps — local, no keys\\n\\nVibe videos (抖音/Reels explainers) usually need narration and a music bed. All of this runs locally on the user's computer with no API key; install under `<root>\\\\.ra-media-tools\\\\`.\\n\\n**Voice-over (Qwen3-TTS, Apache-2.0).** This is a **multi-GB** first download (PyTorch + weights), potentially substantial disk use and GPU load. **Ask the user for explicit approval of the approximate download size and destination before any install, model fetch or inference.** Requesting narration is not consent to an unbounded installation. If approval is absent, do not download Qwen; offer the user's own recorded voice, captions-only delivery, or a simple local audio bed instead. A dedicated NVIDIA GPU makes approved inference faster. Install into a venv: `py -3.11 -m venv venv` then `venv\\\\Scripts\\\\pip install torch torchaudio --index-url https://download.pytorch.org/whl/cu126` and `pip install -U qwen-tts huggingface_hub`; download `Qwen/Qwen3-TTS-12Hz-0.6B-CustomVoice` and `Qwen/Qwen3-TTS-Tokenizer-12Hz` (set `HF_HOME` onto a roomy drive). Synthesize: load `Qwen3TTSModel.from_pretrained(path, device_map=\\\"cuda:0\\\", dtype=torch.float16)`, call `generate_custom_voice(text, language=\\\"Chinese\\\", speaker=\\\"Vivian\\\")` → `wavs, sr`, save with `soundfile.write`. Chinese speakers: Vivian, Serena, Uncle_Fu, Dylan (Beijing), Eric (Sichuan). Write the line's words into a `.vtt` next to the wav so Studio adds subtitles. Then place the wav as an `<audio>` clip in film.html at the shot's second.\\n\\n**Music bed (ACE-Step 1.5, MIT).** Big download (10 GB+ model/dependencies) ; the recipe below targets an NVIDIA GPU (8 GB+ VRAM) and still needs real-device acceptance. Upstream supports other backends, which must be verified separately. **Ask for explicit approval of estimated download/disk use and destination before cloning, `uv sync`, downloading weights or starting an API server.** Never infer consent from a generic music request. Otherwise fall back to the ffmpeg-synth bed above; if approved, bind its local API to loopback only, never a public interface. Install with `uv sync` in a clone of `https://github.com/ACE-Step/ACE-Step-1.5`, start the API `uv run acestep-api --host 127.0.0.1 --port 8001` (with `ACESTEP_OFFLOAD_TO_CPU=true` on 8 GB cards), then `POST http://127.0.0.1:8001/release_task` with `{\\\"prompt\\\":\\\"lofi ambient, soft piano, 72bpm\\\",\\\"lyrics\\\":\\\"\\\",\\\"audio_duration\\\":<seconds>,\\\"model\\\":\\\"acestep-v15-turbo\\\"}`, poll `POST /query_result` with `task_id_list` until `status:1`, and fetch the file via `GET /v1/audio?path=<file>`. Save under `assets/`.\\n\\n**Maps & data (d3-geo + Natural Earth, free).** For map animations (like 来龙去脉 / 冷知识大赏), `npm i d3-geo d3-geo-projection topojson-client` and download Natural Earth GeoJSON (`raw.githubusercontent.com/nvkelso/natural-earth-vector/master/geojson/ne_50m_admin_0_countries.geojson`, provinces, rivers, coastline). In an OpenFilm page, use `d3.geoMercator()`/`geoConicEqualArea()` fitted to the frame and draw country/province paths on canvas, highlighting regions by t. Deterministic (no randomness, no timers), so `look` stays stable.\\n\\n### HyperFrames alternative\\n\\nFor richer scripted motion, HyperFrames (Apache-2.0) also renders HTML→MP4 with GSAP: `npx hyperframes init`, write compositions with `data-start`/`data-duration`, render with `npx hyperframes render`. Same headless-Chromium + FFmpeg pipeline. Use it when the user wants GSAP timelines; otherwise OpenFilm is the default.\\n\\n### Paid providers (user's keys, optional)\\n\\n`npx -y openfilm@0.2.5 get` lists provider-backed media (ElevenLabs, OpenAI, Google, fal) the user connects in Studio with **their own key**. Never ask for or handle keys in chat. AI video clips cost real money: get explicit go-ahead with the expected cost first. Prefer the local, no-key tools above.\\n\\n## Rules\\n\\n- Make the film; do not stop at a plan or storyboard unless the user asked for one.\\n- Use only assets the user owns or code/ffmpeg you generate. Never download other people's media.\\n- OpenFilm starts a local Studio server on first `look`/`render`; it may keep running so the user can edit. Say so; stop it only if the user asks.\\n- Remotion is an alternative only when the user confirms they hold the right Remotion licence.\\n\\n## Device and permission gates\\n\\nRequired authorization scopes: computer:read, computer:write. Running OpenFilm needs the device's `start_process` skill and a Trusted Write Location. Scripts, OS/desktop actions, external service side effects, media generation and paid API usage require independent user-approved execution permissions. This skill does not elevate Remote Arc Tool privileges or authorize use of hidden credentials.\\n\\n## Evidence of completion\\n\\nReport the device, film folder, rendered file path, duration, resolution, frame count, size, render time and anything you could not verify. Do not claim a video exists until ffprobe has read it.\\n\"},{\"id\":\"image-studio\",\"name\":\"Image Studio\",\"priority\":\"P1\",\"category\":\"media\",\"description\":\"Generate, retouch and upscale images using a user-hosted ComfyUI backend.\",\"engine\":\"ComfyUI\",\"requires\":[\"comfy\"],\"scopes\":[\"computer:read\",\"computer:write\"],\"upstream\":\"https://github.com/Comfy-Org/ComfyUI\",\"license\":\"GPL-3.0; weights separate\",\"optIn\":true,\"content\":\"---\\nname: image-studio\\ndescription: Generate, retouch and upscale images using a user-hosted ComfyUI backend.\\npriority: P1\\ncategory: media\\nstatus: builtin-guidance\\n---\\n\\n# Image Studio\\n\\n**Scope:** ComfyUI. **Source:** https://github.com/Comfy-Org/ComfyUI\\n\\n## Workflow\\n\\nDetermine user intent (generate/edit/upscale) and whether their authorized device has a functioning ComfyUI install, compatible accelerator and model license. ComfyUI and its model weights are NOT bundled by Remote Arc; no default GPU/cloud/API spending. Prefer an explicit local HTTP endpoint restricted to loopback, never expose ComfyUI to the internet without authentication. Validate prompt and image sources, request user permission to download third-party weights, run a small trial, inspect output dimensions and safety, write artifacts within approved workspace and report files plus model/provenance. Provide a clear no-backend error instead of claiming an image was made.\\n\\n## Device and permission gates\\n\\nRequired authorization scopes: computer:read, computer:write. Scripts, OS/desktop actions, external service side effects, media generation and paid API usage require independent user-approved execution permissions. This skill does not elevate Remote Arc Tool privileges or authorize use of hidden credentials.\\n\\n## Preflight\\n\\nCheck the engines this skill names before relying on them, with tools you already have (for example `<engine> --version` through start_process, or list_directory on its install folder). Missing executors must be installed explicitly on the correct user device. A Skill being built-in is NOT evidence an engine is present.\\n\\n## Evidence of completion\\n\\nReport input constraints, executed tools and device, verified output path/result, permissions used, cost (if known) and failures. Do not imply successful execution from merely writing a plan.\\n\"},{\"id\":\"ui-inspector\",\"name\":\"UI Inspector\",\"priority\":\"P1\",\"category\":\"desktop\",\"description\":\"Understand screenshot controls with DOM first and optional OmniParser vision.\",\"engine\":\"OmniParser / screenshot tooling\",\"requires\":[\"python3\"],\"scopes\":[\"computer:read\"],\"upstream\":\"https://github.com/microsoft/OmniParser\",\"license\":\"Review repository and model terms\",\"optIn\":true,\"content\":\"---\\nname: ui-inspector\\ndescription: Understand screenshot controls with DOM first and optional OmniParser vision.\\npriority: P1\\ncategory: desktop\\nstatus: builtin-guidance\\n---\\n\\n# UI Inspector\\n\\n**Scope:** OmniParser / screenshot tooling. **Source:** https://github.com/microsoft/OmniParser\\n\\n## Workflow\\n\\nFollow DOM/accessibility tree first for browser pages. For arbitrary desktop screenshots with permission, optionally use OmniParser to identify UI elements and candidate click targets. Treat visual coordinates as guesses: check display scaling, multiple screens, app focus, occlusion and the target before using existing mouse/process tools. Do not auto-install large vision model weights, silently send private screenshots to hosted APIs, or act based on a low-confidence bounding box. Use cropped screenshots only with explicit consent. Verify each mutation by a fresh screenshot or accessibility snapshot; stop after repeated misses.\\n\\n## Device and permission gates\\n\\nRequired authorization scopes: computer:read. Scripts, OS/desktop actions, external service side effects, media generation and paid API usage require independent user-approved execution permissions. This skill does not elevate Remote Arc Tool privileges or authorize use of hidden credentials.\\n\\n## Preflight\\n\\nCheck the engines this skill names before relying on them, with tools you already have (for example `<engine> --version` through start_process, or list_directory on its install folder). Missing executors must be installed explicitly on the correct user device. A Skill being built-in is NOT evidence an engine is present.\\n\\n## Evidence of completion\\n\\nReport input constraints, executed tools and device, verified output path/result, permissions used, cost (if known) and failures. Do not imply successful execution from merely writing a plan.\\n\"},{\"id\":\"transcribe-subtitles\",\"name\":\"Transcribe & Subtitles\",\"priority\":\"P1\",\"category\":\"media\",\"description\":\"Transcribe audio or video to timed subtitles (SRT/VTT) locally with whisper.cpp — auto-installed on first use, no API key, works for Chinese and English.\",\"engine\":\"whisper.cpp + FFmpeg\",\"requires\":[\"ffmpeg\"],\"scopes\":[\"computer:read\",\"computer:write\"],\"upstream\":\"https://github.com/ggml-org/whisper.cpp\",\"license\":\"MIT; model weights separate\",\"optIn\":true,\"content\":\"---\\nname: transcribe-subtitles\\ndescription: Transcribe audio or video to timed subtitles (SRT/VTT) locally with whisper.cpp — auto-installed on first use, no API key, works for Chinese and English.\\npriority: P1\\ncategory: media\\nstatus: builtin-guidance\\n---\\n\\n# Transcribe & Subtitles\\n\\n**Engine:** whisper.cpp (MIT) + FFmpeg, run locally. **Source:** https://github.com/ggml-org/whisper.cpp\\n\\nTranscription has **no paid API requirement** and keeps recordings on the selected computer. Downloads, device compute, electricity and storage still have costs; the calling AI can consume its plan allowance. For the user's own audio/video, deliver the finished `.srt`/`.vtt` (and burned-in subtitles if asked); do not stop at a plan.\\n\\n## Preflight and bounded local install\\n\\nNeed FFmpeg (`ffmpeg -version`) and a whisper.cpp build with a model. Use an existing verified installation first. If absent, the calling AI may provision a **small, pinned** whisper.cpp executable and `ggml-base.bin` (~142 MB) into a Trusted Write Location without another approval *only if* the user already authorized local dependency installation and sufficient space/network are available. Tell them the source, total size and destination before starting. Do not silently install system-level FFmpeg, request administrator rights, execute arbitrary downloaded scripts or exceed the small default. If the download fails, report it instead of claiming subtitles are ready.\\n\\nWindows (cmd/PowerShell), GPU build + a model (~272 MB binary, model 142 MB–1.6 GB):\\n- Binary (NVIDIA): download `https://github.com/ggml-org/whisper.cpp/releases/download/b5454/whisper-bin-win-cuda-11.8.0-x64.zip` and extract with `tar -xf`. No NVIDIA GPU: use `whisper-bin-x64.zip` from the same release (CPU).\\n- **Default model:** `ggml-base.bin` (~142 MB), fetched from `https://huggingface.co/ggerganov/whisper.cpp/resolve/main/ggml-base.bin`. `ggml-small.bin` (~466 MB) or `ggml-large-v3-turbo.bin` (~1.6 GB) require explicit size-aware consent before downloading. Never fetch the largest model by default.\\n- macOS/Linux: use an existing whisper.cpp binary, or explain an approved local `brew install whisper-cpp` / source build; do not silently change system packages. Use the same bounded model policy.\\n\\nCheck release integrity (official source and published checksum when available), verify the archive contents before extraction, and preserve the Windows DLLs beside `whisper-cli.exe`. Confirm the executable actually launches. A downloaded file is not proof that transcription works.\\n\\n## Workflow\\n\\n1. Inspect the input: `ffprobe -v error -show_entries format=duration -of default=nk=1:nw=1 <file>`. Warn if very long (CPU transcription is slow).\\n2. Extract 16 kHz mono WAV: `ffmpeg -y -i <input> -ar 16000 -ac 1 -c:a pcm_s16le audio16k.wav`.\\n3. Transcribe. Chinese: `whisper-cli -m <model>.bin -f audio16k.wav -l zh -osrt -ovtt -of out`. Auto language: `-l auto`. Add `-ml 1` for word-level timing only if the user wants karaoke/animated captions.\\n4. Read `out.srt`, fix obvious recognition errors against the audio; never invent dialogue or speaker labels that evidence does not support.\\n5. Optional burn-in: `ffmpeg -y -i <video> -vf \\\"subtitles=out.srt:force_style='FontName=Noto Sans SC,FontSize=18'\\\" -c:a copy subbed.mp4` (use a CJK font that exists on the device for Chinese).\\n6. Verify with ffprobe; deliver the `.srt`/`.vtt` (and `subbed.mp4` if burned). For OpenFilm videos, put the matching `.vtt` next to its clip so Studio shows subtitles.\\n\\n## Rules\\n\\n- Never upload personal recordings to any service; this runs entirely on the device.\\n- Do not claim accuracy without reviewing a sample against the audio.\\n\\n## Device and permission gates\\n\\nRequired authorization scopes: computer:read, computer:write. Running whisper needs the device's `start_process` skill and a Trusted Write Location. Scripts, OS/desktop actions, external service side effects and paid API usage require independent user-approved execution permissions. This skill does not elevate Remote Arc Tool privileges or authorize use of hidden credentials.\\n\\n## Evidence of completion\\n\\nReport the device, input, model used, output file paths, duration covered, and anything you could not verify. Do not claim subtitles exist until you have read the generated file.\\n\"},{\"id\":\"research-reports\",\"name\":\"Research & Reports\",\"priority\":\"P0\",\"category\":\"productivity\",\"description\":\"Gather cited evidence from authorized sources and create reproducible reports.\",\"engine\":\"Browser Operator + existing file tools\",\"requires\":[],\"scopes\":[\"browser:read\",\"computer:read\",\"computer:write\"],\"upstream\":\"https://github.com/microsoft/playwright-mcp\",\"license\":\"RA authored skill instructions\",\"optIn\":false,\"content\":\"---\\nname: research-reports\\ndescription: Gather cited evidence from authorized sources and create reproducible reports.\\npriority: P0\\ncategory: productivity\\nstatus: builtin-guidance\\n---\\n\\n# Research & Reports\\n\\n**Scope:** Browser Operator + existing file tools. **Source:** https://github.com/microsoft/playwright-mcp\\n\\n## Workflow\\n\\nDefine a precise research question, time window, and trustworthy sources. Read page text via existing authorized browser tools where possible; for bulk web automation opt-in to Browser Operator. Maintain source URLs and timestamps; separate fact from inference and avoid invented citations. Synthesize clear claims with a supporting evidence table, flag uncertainty and contradicting sources. Deliver Markdown, HTML or a requested artifact in a user-authorized workspace; verify paths, file content and citations. Never scrape sites in violation of user scope or access private pages without explicit authorization.\\n\\n## Device and permission gates\\n\\nRequired authorization scopes: browser:read, computer:read, computer:write. Scripts, OS/desktop actions, external service side effects, media generation and paid API usage require independent user-approved execution permissions. This skill does not elevate Remote Arc Tool privileges or authorize use of hidden credentials.\\n\\n## Preflight\\n\\nCheck the engines this skill names before relying on them, with tools you already have (for example `<engine> --version` through start_process, or list_directory on its install folder). Missing executors must be installed explicitly on the correct user device. A Skill being built-in is NOT evidence an engine is present.\\n\\n## Evidence of completion\\n\\nReport input constraints, executed tools and device, verified output path/result, permissions used, cost (if known) and failures. Do not imply successful execution from merely writing a plan.\\n\"},{\"id\":\"scheduled-routines\",\"name\":\"Scheduled Routines\",\"priority\":\"P0\",\"category\":\"productivity\",\"description\":\"Create repeatable, bounded, resumable tasks using the existing Remote Arc scheduler.\",\"engine\":\"Remote Arc automation runtime\",\"requires\":[],\"scopes\":[\"automation:read\",\"automation:write\"],\"upstream\":\"https://remotearc.app\",\"license\":\"RA authored skill instructions\",\"optIn\":false,\"content\":\"---\\nname: scheduled-routines\\ndescription: Create repeatable, bounded, resumable tasks using the existing Remote Arc scheduler.\\npriority: P0\\ncategory: productivity\\nstatus: builtin-guidance\\n---\\n\\n# Scheduled Routines\\n\\n**Scope:** Remote Arc automation runtime. **Source:** https://remotearc.app\\n\\n## Workflow\\n\\nUse Remote Arc's existing automation/goal scheduler; this is a method, not a new MCP tool. Agree on trigger, goal, authorized device, permitted apps and paths, output artifact, spending/time budgets, review gates and stop condition. Prefer event-driven checks before calling a model; keep idempotent checkpoints, bounded retries and an audit trail. Pause and resume without losing task state. Explicit confirmation is required for outgoing emails, publishing, purchases and destructive actions. Validate actual outcome using source-of-truth data before marking complete. If the device is asleep/offline, park the run rather than claiming success. Never schedule unbounded paid API loops.\\n\\n## Device and permission gates\\n\\nRequired authorization scopes: automation:read, automation:write. Scripts, OS/desktop actions, external service side effects, media generation and paid API usage require independent user-approved execution permissions. This skill does not elevate Remote Arc Tool privileges or authorize use of hidden credentials.\\n\\n## Preflight\\n\\nCheck the engines this skill names before relying on them, with tools you already have (for example `<engine> --version` through start_process, or list_directory on its install folder). Missing executors must be installed explicitly on the correct user device. A Skill being built-in is NOT evidence an engine is present.\\n\\n## Evidence of completion\\n\\nReport input constraints, executed tools and device, verified output path/result, permissions used, cost (if known) and failures. Do not imply successful execution from merely writing a plan.\\n\"}]");
